impl LongOperation for SaveAsUseCase {
    type Output = SaveAsResultDto;

    fn execute(
        &self,
        progress_callback: Box<dyn Fn(OperationProgress) + Send>,
        cancel_flag: Arc<AtomicBool>,
    ) -> Result<Self::Output> {
        progress_callback(OperationProgress::new(0.0, Some("Saving…".to_string())));
        if self.dto.file_name.trim().is_empty() {
            return Err(anyhow!("a target .skrib path is required"));
        }

        let now = chrono::Utc::now();
        let mut uow = self.uow_factory.create();
        uow.begin_transaction()?;

        let result = run_save_as(
            &*uow,
            &self.dto.file_name,
            self.dto.as_folder,
            now,
            &progress_callback,
            &cancel_flag,
        );

        match result {
            Ok((work_id, output_path)) => {
                uow.commit()?;
                uow.publish_save_as_event(vec![work_id], None);
                progress_callback(OperationProgress::new(100.0, Some("completed".to_string())));
                Ok(SaveAsResultDto { output_path })
            }
            Err(e) => {
                let _ = uow.rollback();
                Err(e)
            }
        }
    }
}

fn run_save_as(
    uow: &dyn SaveAsUnitOfWorkTrait,
    file_name: &str,
    as_folder: bool,
    now: chrono::DateTime<chrono::Utc>,
    progress: &(dyn Fn(OperationProgress) + Send),
    cancel: &AtomicBool,
) -> Result<(EntityId, String)> {
    let forced = if as_folder {
        SkribShape::ExplodedFolder
    } else {
        SkribShape::ZipFile
    };
    let g = work_io::gather(uow, progress, cancel)?;
    let (target, shape, tag) =
        work_io::resolve_target(file_name, g.work_info.as_ref(), Some(forced))?;
    let work_id = g.work.id;
    let output = work_io::serialize_and_write(&g, target, shape, tag)?;

    if let Some(wi) = &g.work_info {
        let new_shape = if as_folder {
            WorkShape::Folder
        } else {
            WorkShape::Zip
        };
        uow.update_work_info(&WorkInfo {
            id: wi.id,
            created_at: wi.created_at,
            updated_at: now,
            file_name: Some(output.clone()),
            shape: new_shape,
        })?;
    }
    Ok((work_id, output))
}
